import {heatmapSVG,quantumCurveSVG as curve} from './quantum-plots.js?v=20261029-math1';
export const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const num=x=>Number.isFinite(x)?(x!==0&&(Math.abs(x)>=1e5||Math.abs(x)<1e-3)?x.toExponential(4):Number(x.toPrecision(5))):'—';
export const table=(heads,rows)=>`<div class="obs-table"><table><thead><tr>${heads.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
export const notes=rows=>(rows||[]).length?`<aside class="mr-scope"><ul>${rows.map(v=>`<li>${esc(v)}</li>`).join('')}</ul></aside>`:'';
export const sources=rows=>`<div class="obs-sources">${(rows||[]).filter(s=>/^https:\/\//.test(s.url||'')).map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noreferrer">${esc(s.title)} ↗</a>`).join('')}</div>`;
export const fields={
 hall:[['mass','质量参数 m',-1,-5,5,.05],['energyScale','能量尺度（eV）',1,.02,5,.02],['temperature','温度（K）',300,0,5000,10],['chemicalPotential','化学势 μ（eV）',0,-20,20,.01],['mesh','每方向积分网格 N',61,15,121,1],['muMin','μ 扫描起点（eV）',-3.5,-20,20,.1],['muMax','μ 扫描终点（eV）',3.5,-20,20,.1],['scanPoints','扫描点数',61,11,101,1]],
 device:[['model','器件模型','uniform',[['uniform','均匀链'],['ssh','SSH 交替键链']]],['sites','器件格点数',12,2,40,1],['hopping','基准跃迁（eV）',1,.05,5,.01],['dimerRatio','SSH 胞内 / 胞间跃迁比 t₁/t₂',.6,.05,3,.05],['gate','均匀栅压能（eV）',0,-10,10,.1],['barrier','局域势垒高度（eV）',0,-10,10,.1],['barrierStart','势垒起始格点（从 0 编号）',5,0,39,1],['barrierWidth','势垒格点数',1,1,40,1],['leadHopping','电极跃迁（eV）',1,.05,5,.01],['leadOnsite','电极在位能（eV）',0,-10,10,.1],['contactLeft','左接触跃迁（eV）',1,0,5,.01],['contactRight','右接触跃迁（eV）',1,0,5,.01],['energy','观察能量（eV）',.2,-20,20,.01],['energyMin','扫描能量起点（eV）',-2.5,-20,20,.1],['energyMax','扫描能量终点（eV）',2.5,-20,20,.1],['samples','扫描点数',121,41,301,1],['eta','Green 函数展宽 η（eV）',1e-7,1e-9,1e-3,'any'],['spinDegeneracy','独立自旋通道数',1,[[1,'1 · 无自旋模型'],[2,'2 · 两个相同独立自旋通道']]]],
 multiplet:[['electrons','d 壳层电子数 N',6,0,10,1],['coordination','理想晶场','octahedral',[['octahedral','八面体 Oₕ'],['tetrahedral','四面体 Tᵈ']]],['splitting','晶场分裂 Δ（eV）',1,0,10,.05],['coulombU','同轨道排斥 U（eV）',4,0,20,.1],['hundJ','Hund 耦合 J（eV）',.6,0,2,.05],['scanMax','Δ 扫描上限（eV）',5,.1,10,.1],['scanPoints','Δ 扫描点数',21,3,41,1]]
};
export const defaultInputs=Object.fromEntries(Object.entries(fields).map(([id,list])=>[id,Object.fromEntries(list.map(f=>[f[0],f[2]]))]));
export const modelNotes={hall:'二维 QWZ 教学模型；σₓᵧ 是内禀片霍尔电导，αₓᵧ 是横向热电系数。αₓᵧ 不直接等于开路 Nernst 电压。',device:'小规模双端相干、弹性、非相互作用输运。观察能量等于零温线性响应的费米能；键通量不是有限偏压下的实际电流。',multiplet:'固定电子数的五轨道 Kanamori 模型，无 SOC；包含自旋翻转与成对跃迁。要求 U ≥ 3J，不模拟完整 Slater 多重态或真实材料光谱。'};
const select=(id,rows,value)=>`<select id="${id}">${rows.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select>`;
export function controlsHTML(module,input){return fields[module].map(([key,label,def,min,max,step])=>`<label>${esc(label)}${Array.isArray(min)?select('rp-'+key,min,input[key]??def):`<input id="rp-${key}" type="number" min="${min}" max="${max}" step="${step}" value="${esc(input[key]??def)}">`}</label>`).join('')+`<p class="obs-small">${esc(modelNotes[module])}</p>`;}
export function readControls(module,root,previous={}){const out={...previous};for(const [key,,def]of fields[module]){const value=root.querySelector('#rp-'+key).value;if(typeof def==='number'){if(!String(value).trim()||!Number.isFinite(Number(value)))throw Error('数值参数须为有限数字，不能留空。');out[key]=Number(value);}else out[key]=value;}return out;}
function checksHTML(r){return `<details class="qm-checks"><summary>数值校验与分步推导依据</summary>${table(['检查项','结果'],Object.entries(r.checks||{}).filter(([,v])=>['number','string','boolean'].includes(typeof v)).map(([k,v])=>[k,typeof v==='number'?num(v):typeof v==='boolean'?(v?'是':'否'):v]))}${(r.derivation||[]).map(s=>typeof s==='string'?`<p>${esc(s)}</p>`:`<h4>${esc(s.title)}</h4><div class="obs-formula">${esc(s.formula)}</div><p>${esc(s.text||s.explanation)}</p>`).join('')}</details>`;}
function hallSeries(r,key){return [true,false].map(resolved=>({label:resolved?'两网格比较已稳定':'需要加密核验',points:r.scan.rows.map((s,i)=>[r.scan.chemicalPotentials[i],s.defined&&s.numericallyResolved===resolved?s[key]:null])}));}
export function deviceDiagram(r){const n=r.device.sites.length,x=i=>85+510*i/Math.max(1,n-1);return `<svg class="rp-device" viewBox="0 0 700 200" role="img" aria-label="左右电极连接的一维器件"><title>节点颜色表示在位能正负；线宽表示跃迁大小</title><rect x="12" y="54" width="45" height="84" rx="8" fill="#d2e5dd"/><rect x="640" y="54" width="45" height="84" rx="8" fill="#d2e5dd"/><text x="12" y="35">左极</text><text x="637" y="35">右极</text><path d="M57 95H85M595 95H640" stroke="#658575" stroke-width="3" stroke-dasharray="5 4"/>${r.device.bonds.map(b=>`<line x1="${x(b.from)}" x2="${x(b.to)}" y1="95" y2="95" stroke="#427e6a" stroke-width="${Math.min(8,1+3*Math.abs(b.hopping))}"><title>t=${num(b.hopping)} eV</title></line>`).join('')}${r.device.sites.map(s=>`<circle cx="${x(s.index)}" cy="95" r="${n>24?5:8}" fill="${s.onsite>1e-9?'#b77f42':s.onsite< -1e-9?'#567aa5':'#27806a'}"><title>格点 ${s.index}；在位能 ${num(s.onsite)} eV</title></circle>${n<=16||s.index%5===0||s.index===n-1?`<text x="${x(s.index)}" y="130" text-anchor="middle">${s.index}</text>`:''}`).join('')}<text x="350" y="180" text-anchor="middle">有限散射区 · ${n} 个格点</text></svg>`;}
export function resultHTML(module,r){let out='';if(module==='hall'){
 const s=r.selection;out=table(['物理量','结果'],[['σₓᵧ（e²/h）',num(s.sigmaInE2OverH)],['σₓᵧ（S，片响应）',num(s.sigmaXY)],['αₓᵧ（A/K，片响应）',num(s.alphaXY)],['解析直接能隙（eV）',num(r.checks.analyticDirectGap)],['当前积分',s.defined?(s.numericallyResolved?'两网格比较已稳定':'需要加密核验'):'未定义']])+notes([s.reason])+`<h3>横向响应随化学势变化</h3>`+curve(hallSeries(r,'sigmaInE2OverH'),{xLabel:'化学势 μ（eV）',yLabel:'σₓᵧ（e²/h）'})+curve(hallSeries(r,'alphaXY'),{xLabel:'化学势 μ（eV）',yLabel:'αₓᵧ（A/K）'})+notes([`扫描中 ${r.scan.rows.filter(s=>s.defined&&!s.numericallyResolved).length} 个点需要加密核验；${r.scan.rows.filter(s=>!s.defined).length} 个点未定义。绿色表示两网格比较已稳定，棕色为待核验估计；两类之间保留断点。`])+`<details><summary>逐点积分状态与响应</summary>${table(['μ（eV）','σₓᵧ（e²/h）','αₓᵧ（A/K）','状态'],r.scan.rows.map((s,i)=>[num(r.scan.chemicalPotentials[i]),num(s.sigmaInE2OverH),num(s.alphaXY),!s.defined?'未定义':s.numericallyResolved?'两网格比较已稳定':'需要加密核验']))}</details><h3>从几何到占据加权</h3><label>热图内容${select('rp-field',[['berryCurvature','下带 Berry 曲率'],['occupiedCurvature','两带占据加权曲率'],['entropyCurvature','两带熵加权曲率'],['gap','直接能隙（eV）']],'occupiedCurvature')}</label><div id="rp-map"></div><h3>当前 μ、T 的网格比较</h3>`+table(['网格 N','σₓᵧ（S）','αₓᵧ（A/K）','下带曲率积分'],r.convergence.map(c=>[c.mesh,num(c.sigmaXY),num(c.alphaXY),num(c.lowerBandChernIntegral)]));
 }else if(module==='device'){
 const s=r.selection;out=table(['物理量','结果'],[['观察能量（eV）',num(s.energy)],['透射率 T',num(s.transmission)],['反射率 R',num(s.reflection)],['电导（e²/h）',num(s.conductanceQuantum)],['电导（S）',num(s.conductanceSiemens)],['展宽吸收',num(s.regulatorAbsorption)]])+deviceDiagram(r)+curve([{label:'T(E)',points:r.scan.energies.map((e,i)=>[e,r.scan.transmission[i]])}],{xLabel:'能量 E（eV）',yLabel:'透射率 T'})+`<h3>观察能量处的局域谱权重</h3>`+curve([{label:'LDOS',points:s.ldos.map((v,i)=>[i,v])},{label:'左电极注入谱密度',points:s.leftInjectivity.map((v,i)=>[i,v])},{label:'右电极注入谱密度',points:s.rightInjectivity.map((v,i)=>[i,v])}],{xLabel:'格点编号',yLabel:'每自旋谱密度（1/eV）'})+`<h3>左入射键通量</h3>`+curve([{label:'归一化键通量',points:s.bondTransmission.map((v,i)=>[i+.5,v])}],{xLabel:'键中心（格点编号）',yLabel:'每个左入射通道的通量'})+notes(['有限 η 引入微小吸收；应核查通量守恒与 η 比较。电极带外没有传播通道，可能存在局域谱峰，但不能据此报告透射。'])+`<details><summary>展宽收敛详情</summary><pre>${esc(JSON.stringify(r.checks.etaComparison,null,2))}</pre></details>`;
 }else{
 const g=r.ground;out=table(['物理量','结果'],[['固定 N 的 Fock 空间维数',r.dimension],['电子数',r.parameters.electrons],['基态能量（eV）',num(g.energy)],['基态简并度',g.degeneracy],['基态 ⟨S²⟩（ℏ²）',num(g.S2)],['基态自旋 S',g.spins.join(', ')]])+`<h3>选择一个能量与自旋分组</h3><label>多电子能级${select('rp-group',r.groups.map((g,i)=>[i,`${i} · ΔE=${num(g.relativeEnergy)} eV · S=${num(g.spin)} · ${g.degeneracy} 重`]),0)}</label><div id="rp-occupations"></div><h3>晶场增强时的基态变化</h3>`+curve([{label:'⟨S²⟩',points:r.scan.rows.map(s=>[s.splitting,s.S2])}],{xLabel:'晶场分裂 Δ（eV）',yLabel:'基态 ⟨S²⟩（ℏ²）'})+curve([{label:'基态到激发态间隙',points:r.scan.rows.map(s=>[s.splitting,s.gap])}],{xLabel:'晶场分裂 Δ（eV）',yLabel:'激发间隙（eV）'})+`<details><summary>多电子能级表（按能量与 S 分组）</summary>${table(['ΔE（eV）','简并度','S','⟨S²⟩'],r.groups.map(g=>[num(g.relativeEnergy),g.degeneracy,num(g.spin),num(g.S2)]))}</details>`;
 }return out+notes(r.warnings)+checksHTML(r)+sources(r.sources);}
export function bindResult(module,r,root){if(module==='hall'){const field=root.querySelector('#rp-field'),target=root.querySelector('#rp-map');const update=()=>{const h=r.heatmap;target.innerHTML=heatmapSVG(h.kx,h.ky,h[field.value],{title:({berryCurvature:'下带 Berry 曲率',occupiedCurvature:'占据加权曲率',entropyCurvature:'熵加权曲率',gap:'直接能隙'})[field.value],signed:field.value!=='gap',xLabel:'kₓ（rad）',yLabel:'kᵧ（rad）'});};field.onchange=update;field.value='occupiedCurvature';update();}if(module==='multiplet'){const choice=root.querySelector('#rp-group'),target=root.querySelector('#rp-occupations');const update=()=>{const g=r.groups[Number(choice.value)];target.innerHTML=table(['轨道','单电子能量（eV）','该多电子分组的平均占据'],r.orbitalLabels.map((l,i)=>[l,num(r.orbitalEnergies[i]),num(g.orbitalOccupations[i])]))+`<p>同一能量与自旋子空间内平均，五项占据之和为 ${r.parameters.electrons}；单轨道占据范围为 0–2。</p>`;};choice.onchange=update;update();}}
